"""Generate the lifecycle tables from the mk2 policy IR."""

from __future__ import annotations

import argparse
import sys
from collections.abc import Sequence
from pathlib import Path

from vouch_mk2.ir.mk2 import MK2


ROOT = Path(__file__).resolve().parents[1]
LIFECYCLE_PATH = ROOT / "docs" / "lifecycle.md"
HEADER = (
    "<!-- Generated by scripts/gen_lifecycle_doc.py — do not edit; regenerate with "
    "`uv run python scripts/gen_lifecycle_doc.py` -->"
)


def _code_list(values: Sequence[str]) -> str:
    return ", ".join(f"`{value}`" for value in values) or "—"


def render_lifecycle_doc() -> str:
    """Render transitions and adjudication entries in policy IR order."""
    lines = [
        HEADER,
        "",
        "# Lifecycle reference",
        "",
        "The tables show state transitions in the [mk2 policy IR](../src/vouch_mk2/ir/mk2.py).",
        "Gates appear in policy IR order. An em dash marks an empty list.",
        "Use the [command reference](commands.md) for arguments and",
        "[concepts](concepts.md) for the workflow.",
    ]
    for machine in MK2.machines:
        lines.extend((
            "",
            f"## `{machine.name}`",
            "",
            f"Initial state is `{machine.initial}`.",
            "",
            "| From | Command | To | Gates |",
            "|---|---|---|---|",
        ))
        for transition in machine.command_transitions:
            gates = _code_list(transition.gates)
            lines.append(
                f"| `{transition.source}` | `{transition.command}` | "
                f"`{transition.target}` | {gates} |"
            )
        if machine.adjudication_entries:
            lines.extend(("", "| Trigger | To | From | Except |", "|---|---|---|---|"))
            for entry in machine.adjudication_entries:
                sources = _code_list(entry.sources)
                excluded = _code_list(entry.excluded_sources)
                lines.append(f"| `{entry.trigger}` | `{entry.target}` | {sources} | {excluded} |")
    return "\n".join(lines) + "\n"


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="compare without writing")
    parser.add_argument("--output", type=Path, default=LIFECYCLE_PATH, help="target Markdown file")
    arguments = parser.parse_args(argv)
    output: Path = arguments.output
    rendered = render_lifecycle_doc().encode("utf-8")
    if arguments.check:
        if not output.is_file():
            print(f"{output}: missing generated lifecycle reference", file=sys.stderr)
            return 1
        if output.read_bytes() != rendered:
            print(f"{output}: generated lifecycle reference differs", file=sys.stderr)
            return 1
        return 0
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_bytes(rendered)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
